function libro(){
const w=Math.min(innerWidth-28,470),h=Math.min(Math.round(innerHeight*.66),560),hd=`<div class='ph'>${SORPRESA_T.toUpperCase()}</div>`;
const m=document.createElement('div');m.className='meas';m.style.cssText=`position:fixed;left:-9999px;top:0;width:${w}px;visibility:hidden`;document.body.appendChild(m);
const fit=t=>{m.innerHTML=hd+t.map(p=>`<p>${p}</p>`).join('');return m.offsetHeight<=h};
const pgs=[];let cur=[];
CUENTO.forEach(p=>{let rest=p;while(rest){if(fit([...cur,rest])){cur.push(rest);break}const ss=rest.split(/(?<=[.!?…»”])\s+/);let ac='',k=0;while(k<ss.length){const t=ac?ac+' '+ss[k]:ss[k];if(fit([...cur,t])||(!cur.length&&!ac)){ac=t;k++}else break}if(ac)cur.push(ac);rest=ss.slice(k).join(' ');pgs.push(cur);cur=[]}});
if(cur.length)pgs.push(cur);m.remove();
const pages=[`<div class='cv'><svg viewBox='-16 -32 40 42' width='84'>${R(0,0,1)}</svg><h2>${SORPRESA_T}</h2><i>Un cuento para ti</i><div class='orn'>❦</div><small>Toca la página para empezar a leer</small></div>`,
...pgs.map((c,i)=>hd+c.map(p=>`<p>${p}</p>`).join('')+`<div class='pn2'>${i+1}</div>`),
`<div class='cv'><div class='orn'>❦</div><h2>Fin</h2><i>Te amo musho musho</i><svg viewBox='-8 -8 16 16' width='28'>${L(0,0)}</svg></div>`];
const n=pages.length;
open_(`<div class='bkw'><div class='book' style='width:${w}px'><div class='bk' id='bk' style='height:${h}px'><div class='pg under'></div><div class='pg top'></div><div class='rib'></div></div></div><div class='row bn'><button class='x' id='pv'>‹</button><span id='pi'></span><button class='x' id='nx'>›</button></div><div class='row'><button class='x' id='cx'>Volver al tablero</button></div></div>`);
const T=$('#bk .top'),U=$('#bk .under');let i=0,bz=0;
const set=()=>{T.innerHTML=pages[i];U.innerHTML=pages[i+1]||'';$('#pi').textContent=(i+1)+' / '+n};
const next=()=>{if(bz||i>=n-1)return;bz=1;T.classList.add('turn');setTimeout(()=>{i++;T.style.transition='none';T.classList.remove('turn');set();T.offsetWidth;T.style.transition='';bz=0},780)};
const prev=()=>{if(bz||i<=0)return;bz=1;T.style.transition='none';T.innerHTML=pages[i-1];U.innerHTML=pages[i];T.classList.add('turn');T.offsetWidth;T.style.transition='';T.classList.remove('turn');setTimeout(()=>{i--;set();bz=0},780)};
$('#bk').onclick=e=>{const r=e.currentTarget.getBoundingClientRect();e.clientX-r.left<r.width*.3?prev():next()};
$('#nx').onclick=next;$('#pv').onclick=prev;$('#cx').onclick=close_;
const kd=e=>{if(!T.isConnected){document.removeEventListener('keydown',kd);return}if(e.key=='ArrowRight')next();if(e.key=='ArrowLeft')prev()};document.addEventListener('keydown',kd);
set()}
function reloj(){$('header').insertAdjacentHTML('beforeend',`<div id='reloj'><svg viewBox='0 0 100 100' width='76'><circle cx='50' cy='50' r='46' fill='#f3ead6' stroke='#c9a86a' stroke-width='4'/>${[...Array(12)].map((_,i)=>`<path d='M50 8v6' stroke='#3b2418' stroke-width='${i%3?1.5:3}' transform='rotate(${i*30} 50 50)'/>`).join('')}<path id='ah' d='M50 50V28' stroke='#14213d' stroke-width='4' stroke-linecap='round'/><path id='am' d='M50 50V16' stroke='#14213d' stroke-width='3' stroke-linecap='round'/><path id='as' d='M50 56V12' stroke='#b3122b' stroke-width='1.5'/><circle cx='50' cy='50' r='3.5' fill='#6d1a2b'/></svg><div><small>HORA DE BOLIVIA (UTC${ZONA})</small><b id='rh'></b><small id='rc'></small></div></div>`);let last=-1;const tick=()=>{const now=Date.now(),b=new Date(now+ZONA*36e5),hh=b.getUTCHours(),mm=b.getUTCMinutes(),ss=b.getUTCSeconds(),rot=(id,a)=>$('#'+id).setAttribute('transform','rotate('+a+' 50 50)');rot('ah',(hh%12+mm/60)*30);rot('am',mm*6+ss/10);rot('as',ss*6);$('#rh').textContent=p2(hh)+':'+p2(mm)+':'+p2(ss);let nx=-1,ab=8;if(INICIO){ab=0;for(let i=0;i<8;i++)if(now>=abre(i))ab=i+1;if(ab<8)nx=ab}if(nx<0)$('#rc').textContent='Todas las habitaciones están abiertas';else{const d=abre(nx)-now,dd=Math.floor(d/864e5),h2=Math.floor(d%864e5/36e5),m2=Math.floor(d%36e5/6e4),s2=Math.floor(d%6e4/1e3);$('#rc').textContent='Día '+(nx+1)+' se abre en '+(dd?dd+' d ':'')+p2(h2)+':'+p2(m2)+':'+p2(s2)}if(ab!=last){if(last!=-1)draw();last=ab}};tick();setInterval(tick,1000)}
